import { queryRef } from '../html/markup-fragments.ts';

const EDITOR_ONLY_SHELL_MODE = 'editor-only';
const FULL_EDITOR_SHELL_MODE = 'full';

function getEditorShellMode() {
  if (typeof document === 'undefined') {
    return FULL_EDITOR_SHELL_MODE;
  }

  return document.documentElement?.dataset.editorShell ===
    EDITOR_ONLY_SHELL_MODE
    ? EDITOR_ONLY_SHELL_MODE
    : FULL_EDITOR_SHELL_MODE;
}

function shouldRegisterBuiltInOpenLyricPlugin() {
  return getEditorShellMode() !== EDITOR_ONLY_SHELL_MODE;
}

function getDefaultPanelVisibilityForCurrentPage() {
  const hasEditorPanel = queryRef('editorPanel') instanceof HTMLElement;
  const hasPreviewPanel = queryRef('previewPanel') instanceof HTMLElement;
  const hasOpenLyricPanel = queryRef('openLyricPanel') instanceof HTMLElement;

  if (getEditorShellMode() === EDITOR_ONLY_SHELL_MODE) {
    return {
      editorVisible: hasEditorPanel,
      previewVisible: false,
      openLyricVisible: false,
    };
  }

  if (hasOpenLyricPanel) {
    return {
      editorVisible: false,
      previewVisible: false,
      openLyricVisible: true,
    };
  }

  if (hasPreviewPanel) {
    return {
      editorVisible: false,
      previewVisible: true,
      openLyricVisible: false,
    };
  }

  return {
    editorVisible: hasEditorPanel,
    previewVisible: false,
    openLyricVisible: false,
  };
}

export {
  EDITOR_ONLY_SHELL_MODE,
  FULL_EDITOR_SHELL_MODE,
  getDefaultPanelVisibilityForCurrentPage,
  getEditorShellMode,
  shouldRegisterBuiltInOpenLyricPlugin,
};
